import { readFileSync } from 'node:fs'

import { describe, expect, it } from 'vitest'

/**
 * `src/ui/design/panel.html` is generated by `scripts/build-panel.mjs` from
 * `src/ui/design/panel/`. Kilo and OpenCode embed exactly this file, so it must
 * stay one self-contained page with the prototype shell and the legacy
 * transport — no sibling CSS/JS requests, no dev-server configuration.
 */
const page = readFileSync(new URL('../src/ui/design/panel.html', import.meta.url), 'utf8')

describe('shared panel page', () => {
  it('is a generated, self-contained document', () => {
    expect(page).toMatch(/^<!doctype html>/)
    expect(page).toContain('Generated by scripts/build-panel.mjs')
    expect(page).not.toContain('<link rel="stylesheet"')
    expect(page).not.toMatch(/<script[^>]+src=/)
    expect(page).toContain('<style>')
    expect(page.length).toBeGreaterThan(100_000)
    expect(page.length).toBeLessThan(400_000)
  })

  it('renders the accepted prototype shell', () => {
    expect(page).toContain('class="sidebar"')
    expect(page).toContain('id="nav"')
    expect(page).toContain('id="view"')
    expect(page).toContain('id="palette-btn"')
    expect(page).toContain('class="backdrop"')
    expect(page).toContain(':root')
    expect(page).toContain('--accent')
  })

  it('boots from host wiring and the legacy JSON API', () => {
    expect(page).toContain('__LM_PANEL__')
    expect(page).toContain('/api/legacy')
    expect(page).toContain('ui/snapshot?locale=')
    expect(page).toContain('settings/snapshot?locale=')
    expect(page).not.toContain('panel-ui-prototype')
  })
})
